const source = $json;
const sender = source.from || source.sender || source.fromEmail || '';
const emailFrom = (value) => {
  if (typeof value === 'object' && value) {
    return String(value.email || value.address || value.value?.[0]?.address || '').trim();
  }
  const raw = String(value || '').trim();
  const angleMatch = raw.match(/<([^>]+)>/);
  return (angleMatch?.[1] || raw).trim();
};
const fromEmail = emailFrom(sender);
if (!fromEmail) return [];
const rawBody = source.textPlain || source.text || source.snippet || source.textHtml || '';
return [{ json: { gmail_message_id: String(source.id || source.messageId || ''), from_email: fromEmail, subject: String(source.subject || ''), body_preview: String(rawBody).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 4000), received_at: String(source.date || source.internalDate || $now) } }];
